import unittest
from candidate import circular_shift

class TestCircularShift(unittest.TestCase):
    def test_shift_normal_case(self):
        self.assertEqual(circular_shift(12, 1), "21")

    def test_shift_full_cycle(self):
        self.assertEqual(circular_shift(12, 2), "12")

    def test_shift_zero(self):
        self.assertEqual(circular_shift(123, 0), "123")

    def test_shift_negative(self):
        self.assertEqual(circular_shift(123, -1), "123")
        self.assertEqual(circular_shift(123, -10), "123")

    def test_shift_greater_than_length(self):
        self.assertEqual(circular_shift(123, 5), "321")
        self.assertEqual(circular_shift(123456, 10), "654321")

    def test_shift_equal_length(self):
        self.assertEqual(circular_shift(12345, 5), "12345")
        self.assertEqual(circular_shift(-12345, 5), "-12345")

    def test_zero_input(self):
        self.assertEqual(circular_shift(0, 1), "0")
        self.assertEqual(circular_shift(0, 10), "0")

    def test_negative_input(self):
        self.assertEqual(circular_shift(-123, 1), "3-12")
        self.assertEqual(circular_shift(-123, 3), "-123")

    def test_x_as_string(self):
        self.assertEqual(circular_shift("123", 1), "312")
        self.assertEqual(circular_shift("123", 3), "123")

    def test_shift_none_type_error(self):
        with self.assertRaises(TypeError):
            circular_shift(123, None)

    def test_shift_string_type_error(self):
        with self.assertRaises(TypeError):
            circular_shift(123, "1")

    def test_shift_float_type_error(self):
        with self.assertRaises(TypeError):
            circular_shift(123, 1.5)

    def test_large_integer_shift(self):
        big_int = 12345678901234567890
        self.assertEqual(circular_shift(big_int, 5), "90123456789012345678")
        self.assertEqual(circular_shift(big_int, len(str(big_int))), str(big_int))
        self.assertEqual(circular_shift(big_int, len(str(big_int)) + 1), str(big_int)[::-1])

if __name__ == "__main__":
    unittest.main()
